```
module afifo #(
		parameter	LGFIFO = 3,
		parameter	WIDTH  = 16,
		parameter	NFF    = 2,
		parameter [0:0]	WRITE_ON_POSEDGE = 1'b1,
		parameter [0:0]	OPT_REGISTER_READS = 1'b1
	) (
		input	wire			i_wclk, i_wr_reset_n, i_wr,
		input	wire	[WIDTH-1:0]	i_wr_data,
		output	reg			o_wr_full,
		input	wire			i_rclk, i_rd_reset_n, i_rd,
		output	reg	[WIDTH-1:0]	o_rd_data,
		output	reg			o_rd_empty
	);

	localparam	FIFO_DEPTH = 1 << LGFIFO;
	localparam	FIFO_ADDR_WIDTH = LGFIFO;

	reg [WIDTH-1:0] fifo [FIFO_DEPTH-1:0];
	reg [FIFO_ADDR_WIDTH-1:0] wr_ptr, rd_ptr;
	reg [FIFO_ADDR_WIDTH-1:0] wr_ptr_next, rd_ptr_next;
	reg [FIFO_ADDR_WIDTH-1:0] wr_ptr_next_next;
	reg [FIFO_ADDR_WIDTH-1:0] rd_ptr_next_next;
	reg [FIFO_ADDR_WIDTH-1:0] wr_ptr_next_next_next;
	reg [FIFO_ADDR_WIDTH-1:0] rd_ptr_next_next_next;

	reg [NFF-1:0] wr_sync;
	reg [NFF-1:0] rd_sync;

	always @(posedge i_wclk or negedge i_wr_reset_n) begin
		if (~i_wr_reset_n) begin
			wr_ptr <= 0;
			wr_ptr_next <= 0;
			wr_ptr_next_next <= 0;
			wr_ptr_next_next_next <= 0;
			wr_sync <= 0;
		end else begin
			wr_ptr <= wr_ptr_next;
			wr_ptr_next <= wr_ptr_next_next;
			wr_ptr_next_next <= wr_ptr_next_next_next;
			wr_ptr_next_next_next <= wr_ptr_next_next_next_next;
			wr_sync <= {wr_sync[NFF-2:0], i_wr};
		end
	end

	always @(posedge i_rclk or negedge i_rd_reset_n) begin
		if (~i_rd_reset_n) begin
			rd_ptr <= 0;
			rd_ptr_next <= 0;
			rd_ptr_next_next <= 0;
			rd_ptr_next_next_next <= 0;
			rd_sync <= 0;
		end else begin
			rd_ptr <= rd_ptr_next;
			rd_ptr_next <= rd_ptr_next_next;
			rd_ptr_next_next <= rd_ptr_next_next_next;
			rd_ptr_next_next_next <= rd_ptr_next_next_next_next;
			rd_sync <= {rd_sync[NFF-2:0], i_rd};
		end
	end

	always @(*) begin
		wr_ptr_next_next_next_next = wr_ptr_next_next_next;
		rd_ptr_next_next_next_next = rd_ptr_next_next_next;
		if (WRITE_ON_POSEDGE) begin
			if (wr_sync[NFF-1] && ~wr_sync[NFF-2]) begin
				wr_ptr_next_next_next_next = wr_ptr_next_next_next + 1;
			end
		end else begin
			if (~wr_sync[NFF-1] && wr_sync[NFF-2]) begin
				wr_ptr_next_next_next_next = wr_ptr_next_next_next + 1;
			end
		end
		if (rd_sync[NFF-1] && ~rd_sync[NFF-2]) begin
			rd_ptr_next_next_next_next = rd_ptr_next_next_next + 1;
		end
	end

	always @(*) begin
		wr_ptr_next_next_next = wr_ptr_next_next;
		rd_ptr_next_next_next = rd_ptr_next_next;
		if (WRITE_ON_POSEDGE) begin
			if (wr_sync[NFF-1] && ~wr_sync[NFF-2]) begin
				wr_ptr_next_next_next = wr_ptr_next_next + 1;
			end
		end else begin
			if (~wr_sync[NFF-1] && wr_sync[NFF-2]) begin
				wr_ptr_next_next_next = wr_ptr_next_next + 1;
			end
		end
		if (rd_sync[NFF-1] && ~rd_sync[NFF-2]) begin
			rd_ptr_next_next_next = rd_ptr_next_next + 1;
		end
	end

	always @(*) begin
		wr_ptr_next_next = wr_ptr_next;
		rd_ptr_next_next = rd_ptr_next;
		if (WRITE_ON_POSEDGE) begin
			if (wr_sync[NFF-1] && ~wr_sync[NFF-2]) begin
				wr_ptr_next_next = wr_ptr_next + 1;
			end
		end else begin
			if (~wr_sync[NFF-1] && wr_sync[NFF-2]) begin
				wr_ptr_next_next = wr_ptr_next + 1;
			end
		end
		if (rd_sync[NFF-1] && ~rd_sync[NFF-2]) begin
			rd_ptr_next_next = rd_ptr_next + 1;
		end
	end

	always @(*) begin
		wr_ptr_next = wr_ptr;
		rd_ptr_next = rd_ptr;
		if (WRITE_ON_POSEDGE) begin
			if (wr_sync[NFF-1] && ~wr_sync[NFF-2]) begin
				wr_ptr_next = wr_ptr + 1;
			end
		end else begin
			if (~wr_sync[NFF-1] && wr_sync[NFF-2]) begin
				wr_ptr_next = wr_ptr + 1;
			end
		end
		if (rd_sync[NFF-1] && ~rd_sync[NFF-2]) begin
			rd_ptr_next = rd_ptr + 1;
		end
	end

	always @(*) begin
		o_wr_full = (wr_ptr_next_next_next_next == rd_ptr);
		o_rd_empty = (wr_ptr == rd_ptr_next_next_next_next);
	end

	always @(posedge i_wclk or negedge i_wr_reset_n) begin
		if (~i_wr_reset_n) begin
			fifo <= '{default: '0};
		end else begin
			if (wr_sync[NFF-1] && ~wr_sync[NFF-2]) begin
				fifo[wr_ptr_next_next_next_next] <= i_wr_data;
			end
		end
	end

	always @(posedge i_rclk or negedge i_rd_reset_n) begin
		if (~i_rd_reset_n) begin
			o_rd_data <= '0;
		end else begin
			if (rd_sync[NFF-1] && ~rd_sync[NFF-2]) begin
				o_rd_data <= fifo[rd_ptr_next_next_next_next];
			end
		end
	end

